{
  "shared_conditions": [
    "General cleaning guidance concerns grease or oil on metal parts.",
    "CDR-specific guidance concerns cleaning the CDR valve and overrides the stated general choice."
  ],
  "statements": [
    {
      "statement": "For grease or oil on metal parts, the generally specified cleaning agent is a mild detergent or a solvent such as mineral spirits or a petroleum-based cleaner.",
      "answer_quote": "The general cleaning agent specified for grease or oil on metal parts is a mild detergent or a solvent such as mineral spirits or a petroleum-based cleaner"
    },
    {
      "statement": "For grease or oil on metal parts, those general cleaning agents are commonly used because they remove oils and greases effectively without damaging metal surfaces.",
      "answer_quote": "commonly used due to its effectiveness in removing oils and greases without damaging metal surfaces"
    },
    {
      "statement": "The CDR designation refers to a Cylinder Drain Valve.",
      "answer_quote": "CDR (Cylinder Drain Valve)"
    },
    {
      "statement": "The CDR valve contains sensitive internal components, including seals and precision parts.",
      "answer_quote": "the CDR valve contains sensitive internal components, such as seals and precision parts"
    },
    {
      "statement": "The general detergent or solvent choice must not be applied to the CDR valve because it can damage its sensitive internal components.",
      "answer_quote": "this general choice must not be applied to the CDR (Cylinder Drain Valve) because the CDR valve contains sensitive internal components"
    },
    {
      "statement": "When cleaning the CDR valve, solvents or detergents may degrade rubber or plastic materials or cause corrosion.",
      "answer_quote": "solvents or detergents that may degrade rubber or plastic materials or cause corrosion"
    },
    {
      "statement": "The stated authorized CDR valve cleaning method uses a clean, dry cloth.",
      "answer_quote": "The authorized CDR valve cleaning method ... is to use a clean, dry cloth"
    },
    {
      "statement": "The stated authorized CDR valve cleaning method uses a non-abrasive, non-oil-based cleaning agent specifically approved for rubber and plastic components.",
      "answer_quote": "a non-abrasive, non-oil-based cleaning agent specifically approved for use on rubber and plastic components"
    },
    {
      "statement": "When cleaning the CDR valve, gently wipe it with a clean, lint-free cloth to remove surface dirt or debris.",
      "answer_quote": "The valve should be wiped gently with a clean, lint-free cloth to remove surface dirt or debris"
    },
    {
      "statement": "When cleaning the CDR valve, do not use solvent cleaning agents.",
      "answer_quote": "no solvent or oil-based cleaning agents should be used"
    },
    {
      "statement": "When cleaning the CDR valve, do not use oil-based cleaning agents.",
      "answer_quote": "no solvent or oil-based cleaning agents should be used"
    }
  ],
  "excluded_metadata": [
    "Self-described source provenance: “as specified in TM 9-2320-280-20-1, Volume 1 (1996, including Change 2 dated 2004)”.",
    "Citation availability: “[No specific chunk ID available in reference]”."
  ]
}

